        private static void DrawList(SerializedProperty list, string title, bool executors)
        {
            using var box = new EditorGUILayout.VerticalScope(EditorStyles.helpBox);
            list.isExpanded = EditorGUILayout.Foldout(list.isExpanded, $"{title} ({list.arraySize})", true);
            if (!list.isExpanded) return;
            for (var i = 0; i < list.arraySize; i++)
            {
                var item = list.GetArrayElementAtIndex(i);
                using (new EditorGUILayout.VerticalScope(EditorStyles.helpBox))
                {
                    var value = item.managedReferenceValue;
                    if (value == null)
                    {
                        if (GUILayout.Button("创建条目"))
                            item.managedReferenceValue = executors
                                ? new GuideExecutor { executeType = GuideExecuteType.CloseHand }
                                : new GuideEvent { eventType = GuideEventType.OnGuideMaskClick };
                    }
                    else
                    {
                        var enumField = item.FindPropertyRelative(executors ? "executeType" : "eventType");
                        var param = item.FindPropertyRelative(executors ? "executeParam" : "eventParam");
                        var offset = executors ? 1 : 0;
                        EditorGUI.BeginChangeCheck();
                        var chosen = EditorGUILayout.Popup($"#{i + 1} 类型", enumField.intValue - offset,
                            executors ? GuideEditorModel.ExecutorNames : GuideEditorModel.EventNames);
                        if (EditorGUI.EndChangeCheck())
                        {
                            enumField.intValue = chosen + offset;
                            object prototype = executors
                                ? new GuideExecutor { executeType = (GuideExecuteType)(chosen + offset) }
                                : new GuideEvent { eventType = (GuideEventType)chosen };
                            var expected = GuideEditorModel.ParameterType(prototype);
                            // 相同参数结构（如页面打开/关闭）保留已填内容。
                            if (param.managedReferenceValue?.GetType() != expected)
                                param.managedReferenceValue = expected == null ? null : Activator.CreateInstance(expected);
                        }
                        else DrawParameter(param, GuideEditorModel.ParameterType(value));
                    }
                    if (ListButtons(list, i)) return;
                }
            }
            if (GUILayout.Button(executors ? "添加执行器" : "添加事件"))
                Append(list, executors ? new GuideExecutor { executeType = GuideExecuteType.CloseHand }
                    : new GuideEvent { eventType = GuideEventType.OnGuideMaskClick });
        }

        private static bool ListButtons(SerializedProperty list, int index)
        {
            using var row = new EditorGUILayout.HorizontalScope();
            GUILayout.FlexibleSpace();
            using (new EditorGUI.DisabledScope(index == 0))
                if (GUILayout.Button("上移", GUILayout.Width(48))) { list.MoveArrayElement(index, index - 1); return true; }
            using (new EditorGUI.DisabledScope(index == list.arraySize - 1))
                if (GUILayout.Button("下移", GUILayout.Width(48))) { list.MoveArrayElement(index, index + 1); return true; }
            if (!GUILayout.Button("移除", GUILayout.Width(48))) return false;
            list.DeleteArrayElementAtIndex(index);
            return true;
        }

        private static void Append(SerializedProperty list, object value)
        {
            var index = list.arraySize++;
            var item = list.GetArrayElementAtIndex(index);
            item.managedReferenceValue = value;
            item.isExpanded = true;
        }

        private static void DrawParameter(SerializedProperty parameter, Type expected)
        {
            var current = parameter.managedReferenceValue;
            if (expected != null && current?.GetType() != expected)
            {
                EditorGUILayout.HelpBox("参数缺失或类型不匹配。重建会替换旧参数，可撤销。", MessageType.Warning);
                if (GUILayout.Button("创建 / 重建参数")) parameter.managedReferenceValue = Activator.CreateInstance(expected);
                return;
            }
            if (current == null) return;
            if (expected == null)
                EditorGUILayout.HelpBox("此类型不需要参数；现有参数保留，可切换类型或撤销。", MessageType.Info);
            var child = parameter.Copy();
            var end = parameter.GetEndProperty();
            if (!child.NextVisible(true)) return;
            while (!SerializedProperty.EqualContents(child, end))
            {
                Field(child);
                if (!child.NextVisible(false)) break;
            }
        }

        private static void Field(SerializedProperty field)
