        internal static void DrawCondition(SerializedProperty property, string title, string emptyHint, int depth = 0)
        {
            if (depth > 12) { EditorGUILayout.HelpBox("条件嵌套过深或存在循环，请先检查配置。", MessageType.Warning); return; }
            using var box = new EditorGUILayout.VerticalScope(EditorStyles.helpBox);
            var value = property.managedReferenceValue;
            var selection = value switch
            {
                null => 0,
                GuideCondition c when (int)c.conditionType >= 1 && (int)c.conditionType <= 6 => (int)c.conditionType,
                GuideConditionGroup g => g.logicOperator == LogicOperator.And ? 7 : 8,
                _ => -1
            };
            EditorGUI.BeginChangeCheck();
            var chosen = EditorGUILayout.Popup(title, selection, GuideEditorModel.ConditionNames);
            if (EditorGUI.EndChangeCheck())
            {
                // 切换 AND/OR 时保留已有子条件；其他类型替换可通过 Undo 恢复。
                if (value is GuideConditionGroup && chosen >= 7)
                    property.FindPropertyRelative("logicOperator").intValue = chosen == 7 ? 0 : 1;
                else property.managedReferenceValue = GuideEditorModel.CreateCondition(chosen);
                return;
            }
            if (value == null) { EditorGUILayout.LabelField(emptyHint, EditorStyles.miniLabel); return; }
            property.isExpanded = EditorGUILayout.Foldout(property.isExpanded, "参数 / 子条件", true);
            if (!property.isExpanded) return;
            if (value is GuideConditionGroup)
            {
                var list = property.FindPropertyRelative("conditions");
                for (var i = 0; i < list.arraySize; i++)
                {
                    DrawCondition(list.GetArrayElementAtIndex(i), $"子条件 {i + 1}", "空子条件会被忽略", depth + 1);
                    if (ListButtons(list, i)) return;
                }
                if (GUILayout.Button("添加子条件")) Append(list, GuideEditorModel.CreateCondition(1));
            }
            else if (value is GuideCondition)
                DrawParameter(property.FindPropertyRelative("conditionParams"), GuideEditorModel.ParameterType(value));
            else EditorGUILayout.PropertyField(property, new GUIContent("自定义条件"), true);
        }

